//! Regression suite: every fixture's expected output (`*.expected.s`) was
//! generated by running the ORIGINAL `aarch64_assembler_braille.py` on the
//! matching `*.uagl` fixture and saving its output byte-for-byte. This
//! test re-runs the Rust port on the same fixtures and asserts identical
//! output.
//!
//! This all runs as ONE `#[test]` (not eight) deliberately: the compiler's
//! struct/global tables are process-lifetime global state that accumulates
//! across files by design (mirroring the original's own "single Python
//! process" invariant — see the port notes in `README.md`). Rust's test
//! harness runs `#[test]` functions concurrently on separate threads by
//! default, which would race on that shared state; running everything
//! sequentially inside one test sidesteps that entirely, the same way the
//! original avoids it by requiring a single process.

use uagl_aarch64_assembler::{assemble_batch, assemble_uagl_str, validate_uagl_bytes};

const FIXTURES: &[&str] = &[
    "test1_basic",
    "test2_structs",
    "test3_calls",
    "test4_exprs",
    "test5_edge",
    "test6_bug4_repro",
    "test7_bug66_repro",
    "test8_misc",
];

#[test]
fn matches_python_reference_output() {
    for name in FIXTURES {
        let src_path = format!("tests/fixtures/{name}.uagl");
        let expected_path = format!("tests/fixtures/{name}.expected.s");
        let src = std::fs::read_to_string(&src_path)
            .unwrap_or_else(|e| panic!("reading {src_path}: {e}"));
        let expected = std::fs::read_to_string(&expected_path)
            .unwrap_or_else(|e| panic!("reading {expected_path}: {e}"));
        let actual = assemble_uagl_str(&src, &format!("{name}.uagl"));
        assert_eq!(
            actual, expected,
            "{name}: Rust output diverged from the saved Python-reference snapshot"
        );
    }
}

/// The header-file source-name convention (`.weak` instead of `.global`)
/// gets its own fixture-free check since it only affects two lines.
#[test]
fn header_file_uses_weak_symbol() {
    let src = "△ f ○ VOID ═╗\n║ → 0 ◇\n╚═══ 1 ═══╝\n";
    let asm = assemble_uagl_str(src, "decl.h");
    assert!(asm.contains("\t.weak\tf  // header decl"));
    assert!(!asm.contains("\t.global\tf\n"));
}

#[test]
fn unresolved_fallback_is_a_comment_not_a_panic() {
    // Bug #66 in the original: this exact shape is documented as still
    // producing `// unresolved:` rather than a real instruction. Asserting
    // it here pins the *current* (known, documented) behavior so a future
    // change to this codebase is a deliberate choice, not a silent drift.
    let src = "△ f ○ a ─ U64 ─ b ─ U64 ─ VOID ═╗\n\
               ║ · addr ─ U64 ─ 0 ◇\n\
               ║ addr ─ a ─ addr ◇\n\
               ╚═══ 1 ═══╝\n";
    let asm = assemble_uagl_str(src, "f.uagl");
    assert!(asm.contains("// unresolved: a ─ addr"));

    let diagnostics = validate_uagl_bytes(src.as_bytes(), "f.uagl").unwrap();
    assert_eq!(diagnostics.len(), 1);
    assert_eq!(diagnostics[0].line, 3);
    assert_eq!(diagnostics[0].message, "Unresolved expression: a ─ addr");
}

#[test]
fn validation_reports_original_line_and_ignores_comments() {
    let src = "· VALIDATION_ARRAY ─ UINT64[1] ─ {\n\
               ║ 1\n\
               } ◇\n\
               △ validation_probe ○ VOID ═╗\n\
               // unresolved: This is source commentary.\n\
               ║ __asm__ ○ \"// unresolved: This is assembly commentary.\" ◇\n\
               ║ →\n\
               ║ → 0 ◇\n\
               ╚═══ 1 ═══╝\n";
    let diagnostics = validate_uagl_bytes(src.as_bytes(), "validation.uagl").unwrap();
    assert_eq!(diagnostics.len(), 1);
    assert_eq!(diagnostics[0].line, 7);
    assert_eq!(diagnostics[0].message, "Unrecognized UAGL line: ║ →");
}

/// Builds a canonical `.uaglbr` container from scratch (independent of any
/// fixture file) and confirms `decode_uaglbr_bytes` round-trips it, then
/// confirms a bit-flip in the payload is detected. This exercises the
/// same braille encode map, SHA-256, and canonical-JSON logic that was
/// cross-checked against the Python reference during development.
#[test]
fn uaglbr_container_round_trips_and_detects_tampering() {
    use base64::engine::general_purpose::STANDARD as B64;
    use base64::Engine as _;
    use sha2::{Digest, Sha256};
    use uagl_aarch64_assembler::uaglbr::decode_uaglbr_bytes;

    let source = "Hello UAGL 42";
    let src_bytes = source.as_bytes();
    // Nothing is braille-marked in this fixture, so payload == source.
    let payload = src_bytes.to_vec();
    let char_count = source.chars().count();
    let bitmap = vec![0u8; (char_count + 7) / 8];

    let sha256_hex = |data: &[u8]| -> String {
        let mut h = Sha256::new();
        h.update(data);
        h.finalize().iter().map(|b| format!("{:02x}", b)).collect()
    };

    let meta = format!(
        "{{\"bitmap_b64\":\"{}\",\"char_count\":{},\"encoding\":\"utf-8\",\"format\":\"UAGL-BRAILLE-LATIN\",\"payload_sha256\":\"{}\",\"payload_size\":{},\"source_sha256\":\"{}\",\"source_size\":{},\"target_count\":0,\"version\":1}}",
        B64.encode(&bitmap),
        char_count,
        sha256_hex(&payload),
        payload.len(),
        sha256_hex(src_bytes),
        src_bytes.len(),
    );

    let mut container = Vec::new();
    container.extend_from_slice(b"UAGL-BRAILLE-LATIN/1\n");
    container.extend_from_slice(meta.as_bytes());
    container.push(b'\n');
    container.extend_from_slice(&payload);

    let decoded = decode_uaglbr_bytes(&container).expect("valid container should decode");
    assert_eq!(decoded, src_bytes);

    let mut tampered = container.clone();
    let last = tampered.len() - 1;
    tampered[last] ^= 0x01;
    let err = decode_uaglbr_bytes(&tampered).expect_err("tampered payload must be rejected");
    assert!(err.contains("SHA-256"), "unexpected error: {err}");
}

/// Pins the fix for a real bug found while merging this crate into the
/// `ufa_baremetal-rs-v3` workspace: `assemble_batch` used to compile files
/// in a single pass via a `Vec::pop()` work queue (LIFO over an
/// ascending-sorted `Vec`, i.e. *reverse*-alphabetical processing order,
/// further randomized across worker threads), with no struct-discovery
/// pass. A struct *used* in a file that happened to be popped before the
/// file that *defines* it would silently resolve to a wrong, undersized
/// layout — the same class of bug the C port's `UAGL_C_PORT_AUDIT_FINAL.md`
/// documents fixing for a real 30,720-byte `Poly[30]` global that came out
/// as `.zero 0`.
///
/// Struct name is deliberately distinct from every other fixture's structs
/// (`Point`, `Line`, ...) since `tables::STRUCT_TABLE` accumulates
/// process-lifetime state shared with every other `#[test]` in this binary.
///
/// File names are chosen so the definition sorts alphabetically *before*
/// the usage: under the pre-fix `Vec::pop()` order this guarantees the
/// usage file is popped and compiled first, i.e. it deterministically
/// reproduces the bug with `workers = 1` rather than depending on thread
/// scheduling. With the fix (a sequential discovery pass before the real
/// compile), directory order no longer matters at all.
#[test]
fn assemble_batch_resolves_cross_file_struct_regardless_of_directory_order() {
    let root = std::env::temp_dir().join(format!(
        "uagl_batch_order_test_{}_{:?}",
        std::process::id(),
        std::thread::current().id()
    ));
    let in_dir = root.join("in");
    let out_dir = root.join("out");
    std::fs::create_dir_all(&in_dir).expect("create temp in_dir");

    std::fs::write(
        in_dir.join("a_def.uagl"),
        "□ BatchOrderProbe ═╗\n\
         ║ f1 ─ UINT64\n\
         ║ f2 ─ UINT64\n\
         ║ f3 ─ UINT64\n\
         ║ f4 ─ UINT64\n\
         ═╗\n\n\
         △ touch_batch_order_probe ○ VOID ═╗\n\
         ║ → 0 ◇\n\
         ╚═══ 1 ═══╝\n",
    )
    .expect("write a_def.uagl");

    std::fs::write(
        in_dir.join("z_use.uagl"),
        "· batch_order_probe_arr ─ BatchOrderProbe[10] ─ 0 ◇\n\n\
         △ use_batch_order_probe ○ VOID ═╗\n\
         ║ → 0 ◇\n\
         ╚═══ 1 ═══╝\n",
    )
    .expect("write z_use.uagl");

    let result = assemble_batch(
        &in_dir.to_string_lossy(),
        &out_dir.to_string_lossy(),
        1,
    );
    assert_eq!(result.errors, 0, "batch compile reported unexpected errors");

    let generated = std::fs::read_to_string(out_dir.join("z_use.s"))
        .expect("read generated z_use.s");
    assert!(
        generated.contains("batch_order_probe_arr:\n\t.zero\t320"),
        "BatchOrderProbe[10] should resolve to 10 * 32 = 320 bytes regardless \
         of directory processing order; got:\n{generated}"
    );

    let _ = std::fs::remove_dir_all(&root);
}
